content:
cleanup:
        _gnutls_free_datum(&content);
        return result;
}


/**
 * gnutls_pkcs12_get_bag:
 * @pkcs12: A pkcs12 type
 * @indx: contains the index of the bag to extract
 * @bag: An initialized bag, where the contents of the bag will be copied
 *
 * This function will return a Bag from the PKCS12 structure.
 *
 * After the last Bag has been read
 * %GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE will be returned.
 *
 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
 *   negative error value.
 **/
int
gnutls_pkcs12_get_bag(gnutls_pkcs12_t pkcs12,
                      int indx, gnutls_pkcs12_bag_t bag)
{
        ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
        int result, len;
        char root2[MAX_NAME_SIZE];
        char oid[MAX_OID_SIZE];

        if (pkcs12 == NULL) {
                gnutls_assert();
                return GNUTLS_E_INVALID_REQUEST;
        }

        /* Step 1. decode the data.
         */
        result = _decode_pkcs12_auth_safe(pkcs12->pkcs12, &c2, NULL);
        if (result < 0) {
                gnutls_assert();
                return result;
        }

        /* Step 2. Parse the AuthenticatedSafe
         */

        snprintf(root2, sizeof(root2), "?%u.contentType", indx + 1);

        len = sizeof(oid) - 1;
        result = asn1_read_value(c2, root2, oid, &len);

        if (result == ASN1_ELEMENT_NOT_FOUND) {
                result = GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
                goto cleanup;
        }

        if (result != ASN1_SUCCESS) {
                gnutls_assert();
                result = _gnutls_asn2err(result);
                goto cleanup;
        }

        /* Not encrypted Bag
         */

        snprintf(root2, sizeof(root2), "?%u.content", indx + 1);

        if (strcmp(oid, DATA_OID) == 0) {
                result = _parse_safe_contents(c2, root2, bag);
                goto cleanup;
        }

        /* ENC_DATA_OID needs decryption */

        result = _gnutls_x509_read_value(c2, root2, &bag->element[0].data);
        if (result < 0) {
                gnutls_assert();
                goto cleanup;
        }

        bag->element[0].type = GNUTLS_BAG_ENCRYPTED;
        bag->bag_elements = 1;

        result = 0;

      cleanup:
        if (c2)
                asn1_delete_structure(&c2);
        return result;
}

/* Creates an empty PFX structure for the PKCS12 structure.
 */
static int create_empty_pfx(ASN1_TYPE pkcs12)
{
        uint8_t three = 3;
        int result;
        ASN1_TYPE c2 = ASN1_TYPE_EMPTY;

        /* Use version 3
         */
        result = asn1_write_value(pkcs12, "version", &three, 1);
        if (result != ASN1_SUCCESS) {
                gnutls_assert();
                result = _gnutls_asn2err(result);
                goto cleanup;
        }

        /* Write the content type of the data
         */
        result =
            asn1_write_value(pkcs12, "authSafe.contentType", DATA_OID, 1);
        if (result != ASN1_SUCCESS) {
                gnutls_assert();
                result = _gnutls_asn2err(result);
                goto cleanup;
        }

        /* Check if the authenticatedSafe content is empty, and encode a
         * null one in that case.
         */

_parse_safe_contents(ASN1_TYPE sc, const char *sc_name,
                     gnutls_pkcs12_bag_t bag)
{
        gnutls_datum_t content = { NULL, 0 };
        int result;

        /* Step 1. Extract the content.
         */

        result =
            _gnutls_x509_read_string(sc, sc_name, &content,
                                     ASN1_ETYPE_OCTET_STRING, 1);
        if (result < 0) {
                gnutls_assert();
                goto cleanup;
        }

        result = _pkcs12_decode_safe_contents(&content, bag);
        if (result < 0) {
                gnutls_assert();
                goto cleanup;
        }

        _gnutls_free_datum(&content);

        return 0;

      cleanup:
        _gnutls_free_datum(&content);
        return result;
}

unsigned int *chain_len,
                           gnutls_x509_crt_t ** extra_certs,
                           unsigned int *extra_certs_len,
                           gnutls_x509_crl_t * crl, unsigned int flags)
{
        gnutls_pkcs12_bag_t bag = NULL;
        gnutls_x509_crt_t *_extra_certs = NULL;
        unsigned int _extra_certs_len = 0;
        gnutls_x509_crt_t *_chain = NULL;
        unsigned int _chain_len = 0;
        int idx = 0;
        int ret;
        size_t cert_id_size = 0;
        size_t key_id_size = 0;
        uint8_t cert_id[20];
        uint8_t key_id[20];
        int privkey_ok = 0;
        unsigned int i;
        int elements_in_bag;

        *key = NULL;

        if (crl)
                *crl = NULL;

        /* find the first private key */
        for (;;) {

                ret = gnutls_pkcs12_bag_init(&bag);
                if (ret < 0) {
                        bag = NULL;
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_get_bag(p12, idx, bag);
                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
                        gnutls_pkcs12_bag_deinit(bag);
                        bag = NULL;
                        break;
                }
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_bag_get_type(bag, 0);
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                if (ret == GNUTLS_BAG_ENCRYPTED) {
                        if (password == NULL) {
                                ret =
                                    gnutls_assert_val
                                    (GNUTLS_E_DECRYPTION_FAILED);
                                goto done;
                        }

                        ret = gnutls_pkcs12_bag_decrypt(bag, password);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }
                }

                elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
                if (elements_in_bag < 0) {
                        gnutls_assert();
                        goto done;
                }

                for (i = 0; i < (unsigned)elements_in_bag; i++) {
                        int type;
                        gnutls_datum_t data;

                        type = gnutls_pkcs12_bag_get_type(bag, i);
                        if (type < 0) {
                                gnutls_assert();
                                goto done;
                        }

                        ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }

                        switch (type) {
                        case GNUTLS_BAG_PKCS8_ENCRYPTED_KEY:
                                if (password == NULL) {
                                        ret =
                                            gnutls_assert_val
                                            (GNUTLS_E_DECRYPTION_FAILED);
                                        goto done;
                                }

                                FALLTHROUGH;
                        case GNUTLS_BAG_PKCS8_KEY:
                                if (*key != NULL) {     /* too simple to continue */
                                        gnutls_assert();
                                        break;
                                }

                                ret = gnutls_x509_privkey_init(key);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                ret = gnutls_x509_privkey_import_pkcs8
                                    (*key, &data, GNUTLS_X509_FMT_DER,
                                     password,
                                     type ==
                                     GNUTLS_BAG_PKCS8_KEY ?
                                     GNUTLS_PKCS_PLAIN : 0);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                key_id_size = sizeof(key_id);
                                ret =
                                    gnutls_x509_privkey_get_key_id(*key, 0,
                                                                   key_id,
                                                                   &key_id_size);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                privkey_ok = 1; /* break */
                                break;
                        default:
                                break;
                        }
                }

                idx++;
                gnutls_pkcs12_bag_deinit(bag);
                bag = NULL;

                if (privkey_ok != 0)    /* private key was found */
                        break;
        }

        if (privkey_ok == 0) {  /* no private key */
                gnutls_assert();
                return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
        }

        /* now find the corresponding certificate
         */
        idx = 0;
        bag = NULL;
        for (;;) {
                ret = gnutls_pkcs12_bag_init(&bag);
                if (ret < 0) {
                        bag = NULL;
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_get_bag(p12, idx, bag);
                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
                        gnutls_pkcs12_bag_deinit(bag);
                        bag = NULL;
                        break;
                }
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_bag_get_type(bag, 0);
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                if (ret == GNUTLS_BAG_ENCRYPTED) {
                        ret = gnutls_pkcs12_bag_decrypt(bag, password);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }
                }

                elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
                if (elements_in_bag < 0) {
                        gnutls_assert();
                        goto done;
                }

                for (i = 0; i < (unsigned)elements_in_bag; i++) {
                        int type;
                        gnutls_datum_t data;
                        gnutls_x509_crt_t this_cert;

                        type = gnutls_pkcs12_bag_get_type(bag, i);
